#!/usr/bin/env python3
"""
nbt_optdebug_flash.py — STANDALONE, self-contained OPT_DEBUG enable flash for the NBT-Evo HU.

What it does:
  enter the flash bootloader -> SecurityAccess 0x27 / L3 BMWSigVerify (sign the seed with the inlined
  esys L3 key) -> SWDL no-signature file-copy of a patched starter.cfg (OPT_DEBUG STOP->RUN)
  LIVE-DIRECT to /fs/sda0/opt/sys/etc/starter.cfg -> finalize. After the reboot, sshd(22)/telnetd(23)/
  qconn(8000) come up as root over OBD.

  --commit   actually flash (default = DRY-RUN, transmits nothing)
  --revert   flash the byte-exact STOCK starter.cfg instead (undo; same LIVE path)
  --selftest offline self-check: L3 sign round-trips + both inlined blobs pass their sha256

VERSION: the inlined containers carry the 007.051.002 starter.cfg, which is byte-identical across the
whole NBT-Evo 007.xxx family (007_001_016 / 030 / 039 / 049 / 051). Do NOT flash onto a 001_05x unit
(different starter.cfg). The tool reads VIN for logging and warns; it cannot read the exact build, so
confirm the HU is a 007.xxx before --commit.

SAFETY: LIVE-DIRECT write — a bad/wrong-version starter.cfg fails the NEXT boot. This same script IS its
own recovery (`--revert` re-flashes the stock cfg). Run detached (nohup/setsid) so an SSH drop can't tear
the write; the torn-write window is sub-second (CHBJobFileCopy O_TRUNCs+writes only after transferExit).
Serial/eMMC is the ultimate backstop. The L3 key here is the owner's OWN car key — keep this file private.
"""
import argparse, base64, gzip, hashlib, socket, struct, sys, threading, time

# ===================================================================== INLINED L3 FLASH-AUTH KEY
# Owner-local NBT-Evo (BTLD 00001FFD) Level-3 BMWSigVerify key, pre-unwrapped from PSdZData
# (sec_auth_l3.xml, CN=E-SYS-wrapped) so no `cryptography`/XML/PEM is needed at runtime. e=3, 1024-bit.
# Its PUBLIC modulus is byte-embedded in NBTCarHU @0x35c8e0 (non-circular anchor); n_sha256 below.
L3_N = 0xa7377db232dc7d2075623164169f63f483757727b62a3a55d302aef645995ff227de0736bdb43bbc7135a9d015a8824c4b44e7eb71453bf11f65b9f7befc89413f21e6061dbd4811cdd6284f2bcf1ebdd9651d0582990bdc68c940bbf912280f0f9a8072744c6d47ebcdb0d6d404381fb6372c891392f134bb454610a117abbb
L3_D = 0x6f7a53cc21e8536af8ec20ed646a42a3024e4f6fcec6d18e8cac74a42e663ff6c53eaf79d3cd7d284b791be00e7056dd87834547a0d8d2a0bf9926a529fdb0d51627f63d4eb279e1faa034f18db8378355c67afc978f7a1df64aad89710426301f144b6bf29c0c5c8ae1d5bc87b134910bc9f2621fa01dc7ee5b2163971909bb
L3_E = 3
L3_MODLEN = 128
L3_N_SHA256 = "9b0bf6376db090278ff7ff84acb63b191ba9da183226531b8e8b8fd241c714af"

# ===================================================================== INLINED FLASH CONTAINERS
# Minimal no-signature WOODOO file-copy containers (gzip+base64). Each routes a starter.cfg to
# CHBJobFileCopy with TargetPath /fs/sda0/opt/sys/etc/ (LIVE-DIRECT) and carries NO signature record
# (mbSignaturePresent stays 0 -> SwdlMaster accepts). Built from version 007.051.002.
OPTDEBUG_SHA256 = "5620bae39ed8ec27d72121737a9e5eae5b3afd7f4c3b366cec312e319d214834"   # the OPT_DEBUG STOP->RUN container (the enable)
STOCK_SHA256    = "0444ff5623507dfe4294afa4b41105740ceb1ded6a464dded096f299506362e6"      # the byte-exact stock starter.cfg container (the revert)
OPTDEBUG_GZ_B64 = ""
STOCK_GZ_B64    = ""

def load_blob(b64, want_sha):
    raw = gzip.decompress(base64.b64decode(b64))
    got = hashlib.sha256(raw).hexdigest()
    if got != want_sha:
        raise SystemExit("inlined blob integrity FAILED (sha256 %s != %s) — refusing to flash" % (got, want_sha))
    return raw

# ===================================================================== constants (from nbt_link/nbt_flash)
TESTER     = 0xF4
ADDR_HU    = 0x63
ADDR_FUNC  = 0xDF                  # functional broadcast (TesterPresent keepalive)
HSFZ_PORT  = 6801
DIAG_EDGE  = "169.254.199.99"      # HSFZ diag edge if discovery is skipped

# BMW comm-params (PSdZData UDS_BMW_CPS.odx-c / doc fsc/71). Seconds.
P2_MAX     = 2.0
P2_STAR    = 6.5
S3_CLIENT  = 2.0
RECV_TOTAL_MAX = 120.0            # absolute ceiling (long erase keeps emitting 0x78)
MAX_BLOCKSIZE_PROGMODE = 65521
APPMODE_BLOCKSIZE = 4092

# UDS / SWDL
SID_ROUTINE = 0x31
RID_ERASE   = 0xFF00
RID_CHECKMEM= 0x0202
RID_DEPCHECK= 0xFF01
ERASE_METHOD_IE = 0x02
CHECK_METHOD_ICV = 0x12
ERASE_ACTIVATION = 0x06
ALFI        = 0x44
SID_RD      = 0x34
SID_TD      = 0x36
SID_TX      = 0x37
SID_SECACCESS = 0x27
SA_REQSEED  = 0x11
SA_SENDKEY  = 0x12
SID_WDBI    = 0x2E
DID_FINGERPRINT = 0xF15A

NRC = {0x22:"conditionsNotCorrect",0x7E:"subFuncNotSupportedInActiveSession",0x7F:"serviceNotSupportedInActiveSession",
       0x12:"subFunctionNotSupported",0x11:"serviceNotSupported",0x13:"incorrectMessageLengthOrInvalidFormat",
       0x31:"requestOutOfRange",0x33:"securityAccessDenied",0x35:"invalidKey",0x36:"exceedNumberOfAttempts",
       0x37:"requiredTimeDelayNotExpired",0x73:"wrongBlockSequenceCounter",0x21:"busyRepeatRequest",
       0x24:"requestSequenceError",0x78:"responsePending"}

def is_neg(r): return len(r) >= 1 and r[0] == 0x7F

# ===================================================================== HSFZ transport (port of nbt_link.HSFZ)
class HSFZ:
    """BMW HSFZ over TCP. Frame = u32 payload_len | u16 ctrl | [src u8][tgt u8][uds...]."""
    def __init__(self, ip, port=HSFZ_PORT, tester=TESTER, timeout=6.0):
        self.ip, self.port, self.tester, self.timeout = ip, port, tester, timeout
        self.s = None
        self._send_lock = threading.Lock()
        self._tp_stop = None
        self._tp_thread = None
    def open(self):
        self.s = socket.create_connection((self.ip, self.port), timeout=self.timeout)
        self.s.settimeout(self.timeout)
        try:
            self.s.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
            self.s.setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF, 1 << 18)
            self.s.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, 1 << 18)
        except OSError:
            pass
        return self
    def close(self):
        self.stop_tester_present()
        if self.s:
            self.s.close(); self.s = None
    def _send(self, target, uds, ctrl=0x0001):
        payload = bytes([self.tester, target]) + uds
        frame = struct.pack(">IH", len(payload), ctrl) + payload
        with self._send_lock:
            self.s.sendall(frame)
    def _recv_one(self):
        hdr = self._readn(6)
        plen, ctrl = struct.unpack(">IH", hdr)
        payload = self._readn(plen)
        return ctrl, payload[0], payload[1], payload[2:]
    def _readn(self, n):
        buf = b""
        while len(buf) < n:
            c = self.s.recv(n - len(buf))
            if not c:
                raise ConnectionError("HSFZ closed")
            buf += c
        return buf
    def send_only(self, target, uds):
        self._send(target, uds)
    def recv_resp(self, deadline=None, p2=None, p2star=None):
        """BMW P2/P2* windowing: skip ack (0x0002) + async TP ack (0x7E); on 7F xx 78 responsePending
           extend the window by P2*; raise TimeoutError when the window expires."""
        p2     = P2_MAX  if p2     is None else p2
        p2star = P2_STAR if p2star is None else p2star
        start  = time.time()
        hard   = (start + RECV_TOTAL_MAX) if deadline is None else deadline
        window = start + p2
        while True:
            now = time.time()
            cap = min(window, hard)
            if now >= cap:
                raise TimeoutError("no HSFZ response (P2 window expired)")
            self.s.settimeout(max(0.05, cap - now))
            try:
                ctrl, src, tgt, resp = self._recv_one()
            except socket.timeout:
                raise TimeoutError("no HSFZ response (socket timeout)")
            if ctrl == 0x0002:
                continue
            if not resp:
                continue
            if resp[0] == 0x7E:
                continue
            if len(resp) >= 3 and resp[0] == 0x7F and resp[2] == 0x78:
                window = min(hard, time.time() + p2star)
                continue
            return resp
    def request(self, target, uds):
        self.send_only(target, uds)
        return self.recv_resp()
    def start_tester_present(self, period=None, target=ADDR_FUNC, log=None):
        if self._tp_thread is not None:
            return
        period = (S3_CLIENT * 0.5) if period is None else period
        self._tp_stop = threading.Event()
        tp = bytes([0x3E, 0x80])
        def _loop():
            while not self._tp_stop.wait(period):
                try:
                    self._send(target, tp)
                except Exception:
                    break
        self._tp_thread = threading.Thread(target=_loop, name="HSFZ-TP", daemon=True)
        self._tp_thread.start()
        if log:
            log("  [tp] background TesterPresent: 3E 80 -> 0x%02X every %.1fs" % (target, period))
    def stop_tester_present(self):
        if self._tp_stop is not None:
            self._tp_stop.set()
        if self._tp_thread is not None:
            self._tp_thread.join(timeout=1.0)
            self._tp_thread = None
        self._tp_stop = None

# ===================================================================== L3 sign (inlined key; stdlib only)
def md5_input_block(seed, user_id=b"\x00\x00\x00\x00", controller=b"\x00\x00\x1f\xfd"):
    """The exact bytes the bolo MD5-hashes: [UserID:4][Controller:4][seed:8] (seed verbatim)."""
    return bytes(user_id) + bytes(controller) + bytes(seed)

def sign_block(block):
    """BMWSigVerify private op over the MD5 block: s = int_LE(MD5(block))^d mod N; emit LE. Self-verifies
       against the inlined modulus (D'==D and significant-word-count==4) before returning."""
    D = int.from_bytes(hashlib.md5(block).digest(), "little")   # MD5 in low bytes, zero-padded high
    s = pow(D, L3_D, L3_N)
    sig = s.to_bytes(L3_MODLEN, "little")
    Dp = pow(int.from_bytes(sig, "little"), L3_E, L3_N)
    if Dp != D or ((Dp.bit_length() + 31) // 32) != 4:
        raise RuntimeError("L3 SendKey self-verify FAILED — refusing to send a key the ECU would reject")
    return sig

def sendkey_wire(sig):
    """27 12 KEY field = <00 00 00 20> (BE word-count) + 128-byte sig, each 32-bit word byte-reversed."""
    if len(sig) != 128:
        raise ValueError("expected 128-byte LE signature")
    mag = b"".join(sig[i:i + 4][::-1] for i in range(0, 128, 4))
    return (0x20).to_bytes(4, "big") + mag

# ===================================================================== frame builders (port of nbt_flash)
def fr_session(sub):            return bytes([0x10, sub])
def fr_request_seed(tid):       return bytes([SID_SECACCESS, SA_REQSEED]) + bytes(tid)
def fr_send_key(sig):           return bytes([SID_SECACCESS, SA_SENDKEY]) + sendkey_wire(sig)
def fr_write_fingerprint(fp):   return bytes([SID_WDBI, (DID_FINGERPRINT >> 8) & 0xFF, DID_FINGERPRINT & 0xFF]) + bytes(fp)
def fr_transfer_data(seq, blk): return bytes([SID_TD, seq & 0xFF]) + bytes(blk)
def fr_transfer_exit():         return bytes([SID_TX])
def fr_reset(sub=0x01):         return bytes([0x11, sub])
def fr_routine(rid, sub=0x01, *data):
    return bytes([SID_ROUTINE, sub, (rid >> 8) & 0xFF, rid & 0xFF]) + bytes(
        b for d in data for b in (d if isinstance(d, (bytes, bytearray)) else [d]))
def fr_erase_memory(lbn):
    return (bytes([SID_ROUTINE, 0x01, (RID_ERASE >> 8) & 0xFF, RID_ERASE & 0xFF,
                   ERASE_METHOD_IE, ALFI]) + lbn.to_bytes(4, "big") + bytes([ERASE_ACTIVATION]))
def fr_check_memory(lbn):
    return (bytes([SID_ROUTINE, 0x01, (RID_CHECKMEM >> 8) & 0xFF, RID_CHECKMEM & 0xFF,
                   CHECK_METHOD_ICV, ALFI]) + lbn.to_bytes(4, "big") + bytes([0x00, 0x00]))
def fr_request_download(addr, size, dfi=0x00, alfi=ALFI):
    nlen = (alfi >> 4) & 0x0F; nsz = alfi & 0x0F
    return bytes([SID_RD, dfi, alfi]) + addr.to_bytes(nlen, "big") + size.to_bytes(nsz, "big")
def parse_block_length(rd_resp, default=0x400, ceiling=MAX_BLOCKSIZE_PROGMODE):
    if not rd_resp or rd_resp[0] != SID_RD + 0x40 or len(rd_resp) < 3:
        return default
    nbytes = (rd_resp[1] >> 4) & 0x0F
    if nbytes == 0 or len(rd_resp) < 2 + nbytes:
        return default
    maxblk = int.from_bytes(rd_resp[2:2 + nbytes], "big")
    return max(1, min(maxblk - 2, ceiling)) if maxblk > 2 else default

# ===================================================================== prog-mode (port of nbt_progmode)
HU = ADDR_HU
EXT_SESSION  = bytes([0x10, 0x03]); PROG_SESSION = bytes([0x10, 0x02]); HARD_RESET = bytes([0x11, 0x01])
ENERGY_ON = bytes.fromhex("31010F0C03"); ENERGY_OFF = bytes.fromhex("31010F0C00")
DTC_OFF = bytes.fromhex("8502"); DTC_ON = bytes.fromhex("8501")
COMM_QUIET = bytes.fromhex("280301"); COMM_NORMAL = bytes.fromhex("280001")
EXT_SET_01 = bytes.fromhex("3101100301"); EXT_SET_OFF = bytes.fromhex("3101100300")
ACT_APP_MODE = bytes.fromhex("3101100F")
READ_ENERGY = bytes.fromhex("22100A"); READ_EXTMODE = bytes.fromhex("22100E")
READ_FTIMING = bytes.fromhex("222504"); READ_RASS = bytes.fromhex("22F100"); READ_ADS = bytes.fromhex("22F186")

_READS = (READ_ENERGY, READ_EXTMODE, READ_FTIMING, READ_RASS, READ_ADS)
_WRITES = (ENERGY_ON, ENERGY_OFF, DTC_OFF, DTC_ON, COMM_QUIET, COMM_NORMAL, EXT_SET_01, EXT_SET_OFF, ACT_APP_MODE)
def _guard(u):
    u = bytes(u); sid = u[0] if u else -1
    if sid in (0x10, 0x3E): return u
    if u == HARD_RESET:     return u
    if u in _READS or u in _WRITES: return u
    if u == bytes.fromhex("31010203"): return u
    raise AssertionError("REFUSED (prep allowlist): %s" % u.hex())

def _gtx(h, u, label, log):
    try: r = h.request(HU, _guard(u))
    except Exception as e: log("  [tx] %-30s -> ERR %s" % (label, e)); return None
    if r is None: log("  [tx] %-30s -> (none)" % label); return None
    if is_neg(r):
        nrc = r[2] if len(r) > 2 else 0
        log("  [tx] %-30s -> NRC 0x%02X %s" % (label, nrc, NRC.get(nrc, "?")))
    else:
        log("  [tx] %-30s -> %s" % (label, r[:12].hex()))
    return r
def _ispos(r): return r is not None and r[0] != 0x7F
def _val(r): return r[-1] if _ispos(r) and r[0] == 0x62 else None

def enter_progmode(h, reset_timeout, log=print):
    log("== STEP 1: extended session + flash timing ==")
    _gtx(h, EXT_SESSION, "10 03 ExtendedSession", log)
    _gtx(h, READ_FTIMING, "22 2504 FlashTiming", log)
    log("== STEP 2: ActivateFlashMode (EnergyMode=Flash) ==")
    if not _ispos(_gtx(h, ENERGY_ON, "31 01 0F0C 03 ActivateFlash", log)):
        log("  *** HU refused 0F0C 03 — abort. ***"); return False
    if _val(_gtx(h, READ_ENERGY, "22 10 0A EnergyMode", log)) in (None, 0x00):
        log("  *** EnergyMode not set — abort. ***"); return False
    log("== STEP 3: DTC off + CommunicationControl quiet ==")
    _gtx(h, DTC_OFF, "85 02 ControlDTCSetting off", log)
    r = _gtx(h, COMM_QUIET, "28 03 01 CommControl quiet", log)
    if r is not None and is_neg(r) and len(r) > 2 and r[2] == 0x22:
        log("  *** 28 03 01 -> 0x22 (unexpected) ***")
    _gtx(h, READ_RASS, "22 F100 sub-state", log)
    log("== STEP 4: SetExtendedMode (31 01 1003 01) ==")
    r = _gtx(h, EXT_SET_01, "31 01 1003 01 SetExtMode", log)
    if r is None or is_neg(r):
        nrc = r[2] if r and len(r) > 2 else 0
        log("  *** SetExtendedMode NRC 0x%02X — abort. ***" % nrc); return False
    _gtx(h, READ_EXTMODE, "22 10 0E ExtendedMode", log)
    log("== STEP 5: programmingSession (10 02; HU self-reboots app->bootloader; poll 22 F186) ==")
    _gtx(h, EXT_SESSION, "10 03", log)
    _gtx(h, READ_FTIMING, "22 2504 FlashTiming", log)
    r = _gtx(h, PROG_SESSION, "10 02 ProgrammingSession", log)
    if r is not None and is_neg(r) and len(r) > 2 and r[2] == 0x22:
        log("  *** 10 02 -> 0x22 (prep insufficient) — abort. ***"); return False
    log("  [..] 10 02 accepted; HU self-rebooting — polling 22 F186 (<= %ds)" % reset_timeout)
    try: h.close()
    except Exception: pass
    t0 = time.time(); h.timeout = 2.0; sess = None
    while time.time() - t0 < reset_timeout:
        time.sleep(1.0)
        try:
            h.open()
            rr = h.request(HU, _guard(READ_ADS))
            if _ispos(rr) and rr[0] == 0x62 and len(rr) >= 4:
                sess = rr[3]
                log("  [..] HU answering after %.0fs: session 0x%02X" % (time.time() - t0, sess)); break
        except Exception:
            try: h.close()
            except Exception: pass
    h.timeout = 6.0
    if sess == 0x02:
        log("  *** HU in PROGRAMMING SESSION (bootloader). ***"); return True
    if sess is not None:
        log("  HU rebooted to session 0x%02X (not 0x02) — not in bootloader." % sess); return False
    log("  *** HU did not answer 22 F186 within %ds. ***" % reset_timeout); return False

def _reopen(h):
    try: h.close()
    except Exception: pass
    try: h.open()
    except Exception: pass

def _read_state(h, label, log):
    """22 F186 -> HU state byte (01 app, 02 programming/bootloader, 03 flash transition)."""
    r = _gtx(h, READ_ADS, label, log)
    return r[3] if _ispos(r) and r[0] == 0x62 and len(r) >= 4 else None

def teardown(h, log=print):
    """Restore the HU app after any abort.
       Never wait for session 0x01 while EnergyMode is still Flash: in that state the HU
       cannot return to the app on its own, so the old code deadlocked and left the unit on
       a black screen. Clear EnergyMode/ExtendedMode first, then reset. If the registers do
       not read back clean we still force a reset — leaving the HU in EnergyMode=Flash is a
       guaranteed black screen, while a reset lets it boot the app again."""
    log("== TEARDOWN: restore HU to normal app ==")
    _reopen(h); _gtx(h, ACT_APP_MODE, "31 01 100F ActAppMode", log)
    en_ok = ext_ok = False; st = None
    for _ in range(6):
        _reopen(h)
        _gtx(h, EXT_SESSION, "10 03 ExtendedSession", log)
        _gtx(h, ENERGY_OFF, "31 01 0F0C 00 EnergyOff", log)
        en_ok = (_val(_gtx(h, READ_ENERGY, "22 100A EnergyMode", log)) == 0x00)
        _gtx(h, EXT_SET_OFF, "31 01 1003 00 ExtModeOff", log)
        ext_ok = (_val(_gtx(h, READ_EXTMODE, "22 100E ExtendedMode", log)) == 0x00)
        st = _read_state(h, "22 F186 (state)", log)
        if (en_ok and ext_ok) or st == 0x01:
            break
        time.sleep(2.0)
    _gtx(h, COMM_NORMAL, "28 00 01 CommNormal", log)
    _gtx(h, DTC_ON, "85 01 DTC on", log)
    if (en_ok and ext_ok) or st == 0x01:
        _gtx(h, HARD_RESET, "11 01 reset -> clean app", log); return True
    log("  *** NOT clean (energy=%s ext=%s state=%s) — forcing reset to exit flash mode. ***"
        % ("00" if en_ok else "!=00", "00" if ext_ok else "!=00", "?" if st is None else "0x%02X" % st))
    _gtx(h, HARD_RESET, "11 01 reset (force exit flash mode)", log)
    try: h.close()
    except Exception: pass
    t0 = time.time()
    while time.time() - t0 < 25:
        time.sleep(2.0)
        try:
            h.open()
            if _read_state(h, "22 F186 (after reset)", log) == 0x01:
                log("  [..] back in app (session 01) after force reset (%.0fs)" % (time.time() - t0)); return True
        except Exception:
            try: h.close()
            except Exception: pass
    log("  *** HU did not confirm app session after reset. ***")
    return False

# ===================================================================== apply (port of nbt_apply)
def _req(h, uds, label, log, expect_pos=True):
    try:
        r = h.request(HU, uds)
    except Exception as e:
        log("  [tx] %-28s -> ERR %s" % (label, e)); return None, False
    if r is None:
        log("  [tx] %-28s -> (none)" % label); return None, False
    if is_neg(r):
        nrc = r[2] if len(r) > 2 else 0
        log("  [tx] %-28s -> NRC 0x%02X %s" % (label, nrc, NRC.get(nrc, "?")))
        return r, (not expect_pos)
    log("  [tx] %-28s -> %s" % (label, r[:12].hex()))
    return r, True

def _xfer_block(h, seq, chunk):
    frame = fr_transfer_data(seq, chunk)
    last = "?"
    for attempt in range(6):
        try:
            h.send_only(HU, frame)
            while True:
                r = h.recv_resp()
                if not is_neg(r) and len(r) >= 2 and r[0] == 0x76:
                    if r[1] == seq:
                        return True, (None if attempt == 0 else "resent")
                    last = "stale 76 %02x" % r[1]; continue
                if is_neg(r):
                    nrc = r[2] if len(r) > 2 else 0
                    if nrc == 0x73:
                        return True, "0x73-advance"
                    if nrc in (0x21, 0x7F):
                        last = "NRC 0x%02X (resend BSC)" % nrc
                        time.sleep(0.2); break
                    return False, "NRC 0x%02X %s" % (nrc, NRC.get(nrc, "?"))
                last = "unexpected %s" % r[:4].hex(); continue
        except TimeoutError:
            last = "timeout (P2 window)"; time.sleep(0.3)
        except Exception as e:
            last = type(e).__name__; time.sleep(0.4)
    return False, last

def _l3_auth(h, controller, tester_id, log):
    log("\n== SecurityAccess 0x27 / L3 (require 67 12) ==")
    r, ok = _req(h, fr_request_seed(tester_id), "27 11 RequestSeed", log)
    if not ok or not r or r[0] != 0x67:
        log("  *** no seed -> ABORT, nothing written. ***"); return False
    seed = bytes(r[2:])
    blk = md5_input_block(seed, user_id=tester_id, controller=controller)
    log("  MD5 input = %s" % blk.hex())
    sig = sign_block(blk)
    r, ok = _req(h, fr_send_key(sig), "27 12 SendKey", log)
    if not ok or not r or r[0] != 0x67:
        log("  *** auth NOT granted (need 67 12) -> ABORT, nothing written. ***"); return False
    log("  *** L3 auth GRANTED (67 12) ***")
    return True

def _container_target(img):
    try:
        pos, n = 0, len(img)
        while pos + 9 <= n:
            marker = img[pos]
            length = int.from_bytes(img[pos + 3:pos + 7], "little")
            if marker == 0x02:
                meta = img[pos + 9:pos + 9 + length].decode("latin-1", "replace")
                kv = dict(p.split("=", 1) for p in meta.split(";") if "=" in p)
                tp = kv.get("TargetPath", ""); nm = kv.get("Name", "")
                return (tp + nm, nm, bool(tp) and "/repository/istep/" not in tp)
            pos += 9 + length
    except Exception:
        pass
    return None, None, None

def apply_flash(h, img, *, reset_timeout, controller, lbn, fingerprint, tester_id, tp_period=None, log=print):
    if not enter_progmode(h, reset_timeout, log=log):
        log("\n  *** Did not reach bolo session 0x02 — ABORT, NOTHING written. ***"); return False
    if not _l3_auth(h, controller, tester_id, log):
        return False
    h.start_tester_present(period=tp_period, log=log)
    log("\n== SWDL write (%d bytes) ==" % len(img))
    _req(h, fr_write_fingerprint(fingerprint), "2E F15A fingerprint", log, expect_pos=False)
    r, ok = _req(h, fr_erase_memory(lbn), "31 FF00 eraseMemory(IE)", log)
    if not ok:
        log("  *** erase rejected -> ABORT (live file untouched). ***"); teardown(h, log=log); return False
    r, ok = _req(h, fr_request_download(0, len(img)), "34 requestDownload", log)
    if not ok:
        log("  *** requestDownload rejected -> ABORT. ***"); teardown(h, log=log); return False
    block_size = parse_block_length(r)
    nblocks = (len(img) + block_size - 1) // block_size
    log("  maxNumberOfBlockLength -> %d-byte blocks; %d blocks" % (block_size, nblocks))
    seq = 1; t0 = time.time(); recovered = 0
    for i, off in enumerate(range(0, len(img), block_size)):
        chunk = img[off:off + block_size]
        ok, note = _xfer_block(h, seq, chunk)
        if not ok:
            log("  *** transferData block %d/%d FAILED at %.1fs: %s -> ABORT (NOT committed). ***"
                % (i + 1, nblocks, time.time() - t0, note)); return False
        if note: recovered += 1
        if (i % 50 == 0) or (i == nblocks - 1):
            sent = off + len(chunk); kbs = sent / 1024.0 / max(0.001, time.time() - t0)
            log("  [..] block %d/%d ok  (%.0fs, %.1f KB/s, %d recovered)" % (i + 1, nblocks, time.time() - t0, kbs, recovered))
        seq = (seq + 1) & 0xFF
    log("  transfer complete: %d blocks, %.1fs, %d hiccups recovered" % (nblocks, time.time() - t0, recovered))
    r, ok = _req(h, fr_transfer_exit(), "37 transferExit", log)
    if not ok:
        log("  *** transferExit rejected. ***"); return False
    r, ok = _req(h, fr_check_memory(lbn), "31 0202 checkMemory(ICV)", log)
    if not ok:
        log("  *** checkMemory NRC (LBN mismatch?) — proceeding to finalize. ***")
    _req(h, fr_routine(RID_DEPCHECK), "31 FF01 checkProgDeps", log, expect_pos=False)
    tgt, _nm, is_live = _container_target(img)
    if is_live:
        log("\n  *** WRITE SENT — LIVE-DIRECT to %s. Goes live next boot (no linkIStep). ***" % (tgt or "the live path"))
    else:
        log("\n  *** WRITE SENT — staged at %s. ***" % (tgt or "the repo"))
    return True

# ===================================================================== ENET discovery (port of nbtkit.discover)
def discover(timeout=4.0):
    """6811 HSFZ identification broadcast -> (gw_ip, vin). Binds the eth0 link-local source so the
       broadcast egresses the ENET cable, not wlan0. (None, None) on no reply."""
    src = None
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("169.254.1.1", 9)); ip = s.getsockname()[0]; s.close()
        if ip.startswith("169.254."): src = ip
    except Exception:
        pass
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
    try:
        if src: s.bind((src, 0))
    except Exception:
        pass
    s.settimeout(timeout)
    try:
        s.sendto(struct.pack(">IH", 0, 0x0011), ("169.254.255.255", 6811))
        d, a = s.recvfrom(512)
    except socket.timeout:
        return None, None
    finally:
        s.close()
    ident = d[6:].decode("latin1", "replace")
    vin = ident.split("BMWVIN", 1)[1][:17] if "BMWVIN" in ident else None
    return a[0], vin

def read_vin(h):
    try:
        r = h.request(HU, bytes([0x22, 0xF1, 0x90]))
        return r[3:].decode("latin1", "replace").strip("\x00 ") if not is_neg(r) else None
    except Exception:
        return None

# ===================================================================== selftest / main
def selftest():
    print("[selftest] L3 key: RSA-%d e=%d  n_sha256=%s" % (L3_MODLEN * 8, L3_E, L3_N_SHA256))
    got = hashlib.sha256(L3_N.to_bytes(L3_MODLEN, "big")).hexdigest()
    print("  n_sha256 match :", got == L3_N_SHA256)
    ok = (got == L3_N_SHA256)
    for L in (4, 8):
        seed = bytes(range(0x10, 0x10 + L))
        blk = md5_input_block(seed)
        sig = sign_block(blk)                 # raises if self-verify fails
        wire = fr_send_key(sig)
        good = (len(wire) == 134 and wire[:6].hex() == "271200000020")
        print("  seed(%dB): sign+self-verify OK, wire len %d, prefix ok=%s" % (L, len(wire), good))
        ok = ok and good
    od = load_blob(OPTDEBUG_GZ_B64, OPTDEBUG_SHA256)
    st = load_blob(STOCK_GZ_B64, STOCK_SHA256)
    print("  OPT_DEBUG container: %d bytes, sha256 OK" % len(od))
    print("  STOCK    container: %d bytes, sha256 OK" % len(st))
    for nm, img in (("OPT_DEBUG", od), ("STOCK", st)):
        tgt, name, is_live = _container_target(img)
        print("    %-9s -> %s  Name=%s  LIVE-DIRECT=%s" % (nm, tgt, name, is_live))
    print("[selftest] %s" % ("ALL PASS" if ok else "FAILURES PRESENT"))
    return ok

def main():
    ap = argparse.ArgumentParser(description="Standalone OPT_DEBUG enable flash for the NBT-Evo HU (dry-run default).")
    ap.add_argument("--host", default=None, help="gateway HSFZ host (default: 6811 auto-discover, else %s)" % DIAG_EDGE)
    ap.add_argument("--port", type=int, default=HSFZ_PORT)
    ap.add_argument("--commit", action="store_true", help="actually flash (default: dry-run)")
    ap.add_argument("--revert", action="store_true", help="flash the STOCK starter.cfg (undo OPT_DEBUG)")
    ap.add_argument("--reset-timeout", type=int, default=50)
    ap.add_argument("--lbn", default="0", help="logicalBlockNumber hex for indicated erase/checkMemory (default 0)")
    ap.add_argument("--tester-id", default="00000000")
    ap.add_argument("--controller", default="00001ffd")
    ap.add_argument("--fingerprint", default="00" * 13)
    ap.add_argument("--tp-period", type=float, default=None)
    ap.add_argument("--no-discover", action="store_true", help="skip 6811 discovery; use --host/%s" % DIAG_EDGE)
    ap.add_argument("--selftest", action="store_true", help="offline self-check (no car) and exit")
    a = ap.parse_args()

    if a.selftest:
        sys.exit(0 if selftest() else 1)

    which = "STOCK (revert)" if a.revert else "OPT_DEBUG (enable)"
    img = load_blob(STOCK_GZ_B64, STOCK_SHA256) if a.revert else load_blob(OPTDEBUG_GZ_B64, OPTDEBUG_SHA256)
    tgt, name, is_live = _container_target(img)
    lbn = int(a.lbn, 16)
    tester_id = bytes.fromhex(a.tester_id); controller = bytes.fromhex(a.controller); fingerprint = bytes.fromhex(a.fingerprint)

    # resolve gateway
    host = a.host; vin = None
    if not host and not a.no_discover:
        print("Discovering gateway via 6811 broadcast ...")
        host, vin = discover()
        if host: print("  gateway %s   VIN %s" % (host, vin))
    if not host:
        host = DIAG_EDGE
        print("  (no discovery) using %s" % host)

    print("\n=== nbt_optdebug_flash :: %s ===" % which)
    print("container : %d bytes -> %s  [%s]" % (len(img), tgt, "LIVE-DIRECT" if is_live else "STAGING"))
    print("gateway   : %s:%d   LBN=0x%X   controller=%s" % (host, a.port, lbn, controller.hex()))
    print("VERSION   : container is 007.051.002 (== whole 007.xxx family). Do NOT use on a 001_05x unit.")

    if not a.commit:
        print("\nDRY-RUN (no --commit) — transmitting nothing. Planned sequence:")
        for ln in ["[enter bolo] 10 03 -> 0F0C 03 -> 85 02 -> 28 03 01 -> 1003 01 -> 10 02 -> poll 22 F186==02",
                   "27 11 / sign MD5([UserID %s][Controller %s][seed]) / 27 12  -> REQUIRE 67 12" % (tester_id.hex(), controller.hex()),
                   "[tp] background TesterPresent 3E 80 -> 0xDF every ~1.0s",
                   "2E F15A %s" % fingerprint.hex(),
                   "31 01 FF00 02 44 %08X 06        (indicated eraseMemory)" % lbn,
                   "34 00 44 00000000 %08X          (requestDownload)" % len(img),
                   "36 <BSC> <block> x N            (transferData; ~53 app-mode blocks)",
                   "37                              (transferExit)",
                   "31 01 0202 12 44 %08X 00 00     (indicated checkMemory)" % lbn,
                   "31 01 FF01                      (checkProgDeps stub)",
                   "[finalize] 100F ActivateApplicationMode -> clear energy/ext -> 11 01"]:
            print("  " + ln)
        print("\nLIVE-DIRECT: writes the running starter.cfg in place; goes live next boot. A bad cfg fails")
        print("the next boot — recover with `--revert`. Run detached (setsid/nohup) so an SSH drop can't tear it.")
        print("Re-run with --commit to flash.")
        return

    print("\nCOMMIT: flashing now.")
    h = HSFZ(host, port=a.port, timeout=6.0).open()
    try:
        live_vin = read_vin(h)
        if live_vin: print("  HU VIN: %s" % live_vin)
    except Exception:
        pass
    wrote = False
    try:
        wrote = apply_flash(h, img, reset_timeout=a.reset_timeout, controller=controller,
                            lbn=lbn, fingerprint=fingerprint, tester_id=tester_id, tp_period=a.tp_period)
    finally:
        print()
        try: h.stop_tester_present()
        except Exception: pass
        try: teardown(h)
        except Exception as e: print("  [finalize warn] %s" % e)
        try: h.close()
        except Exception: pass
    if wrote:
        if a.revert:
            print("\n=== REVERT WRITE SENT — stock starter.cfg restored. Reboot + verify ssh/qconn are CLOSED. ===")
        else:
            print("\n=== OPT_DEBUG WRITE SENT — wait ~50s for boot, then telnet/ssh root@HU (22/23/8000 open). ===")
    else:
        print("\n=== ABORTED — existing starter.cfg intact, nothing committed ===")

if __name__ == "__main__":
    main()
